      mouthSvg = `
        <ellipse cx="60" cy="64" rx="5" ry="6" fill="#2b3b48" />
        <ellipse cx="60" cy="65" rx="3.5" ry="3.5" fill="#ff4d6d" />
      `;
    } else { // vampire
      mouthSvg = `
        <path d="M 49 61 Q 60 71 71 61" stroke="#2b3b48" stroke-width="2.5" fill="none" />
        <polygon points="53,62 55,67 57,62" fill="#fff" />
