class DojoStore {
  constructor() {
    this.state = dataEngine.loadState(INITIAL_DATA);
    // Ensure all critical properties exist
    if (!this.state.classes || !this.state.classes.length) {
      this.state = JSON.parse(JSON.stringify(INITIAL_DATA));
      dataEngine.saveState(this.state);
    }
    // Listen for storage changes from other tabs or firebase
    window.addEventListener('storage', (e) => {
      if (e.key === dataEngine.storageKey) {
        this.state = dataEngine.loadState(INITIAL_DATA);
        this.notify();
      }
    });
    this.subscribers = new Set();
  }

  subscribe(callback) {
    this.subscribers.add(callback);
    return () => this.subscribers.delete(callback);
  }

  notify() {
    this.subscribers.forEach(cb => {
      try { cb(this.state); } catch (e) { console.error(e); }
    });
  }

  save() {
    dataEngine.saveState(this.state);
    this.notify();
  }

  // Active class getter
  getActiveClass() {
    const cls = this.state.classes.find(c => c.id === this.state.activeClassId);
    return cls || this.state.classes[0];
  }

  setActiveClass(classId) {
    this.state.activeClassId = classId;
    this.save();
  }

  // Add new class
  addClass(name, grade = '三年級') {
    const newClass = {
      id: `cls_${Date.now()}`,
      name,
      grade,
      icon: '🎒',
      code: Math.random().toString(36).substring(2, 8).toUpperCase(),
      totalPoints: 0,
      skills: JSON.parse(JSON.stringify(INITIAL_DATA.classes[0].skills)),
      students: [],
      groups: []
    };
    this.state.classes.push(newClass);
    this.state.activeClassId = newClass.id;
    this.save();
    return newClass;
  }

  // Add student
  addStudent(classId, studentName) {
    const cls = this.state.classes.find(c => c.id === classId);
    if (!cls) return null;

    const newStudent = {
      id: `stu_${Date.now()}`,
      name: studentName,
      seatNumber: cls.students.length + 1,
      points: 0,
      isHatched: false, // Start as egg like authentic ClassDojo!
      seed: `${studentName}_${Date.now()}`,
      attendance: 'present',
      parentName: `${studentName.slice(0, 1)}家長`,
      parentCode: `P-${Math.random().toString(36).substring(2, 6).toUpperCase()}`,
      history: []
    };
    cls.students.push(newStudent);
    this.save();
    return newStudent;
  }

  // Award points to individual student
  awardStudentPoint(classId, studentId, skill) {
    const cls = this.state.classes.find(c => c.id === classId);
    if (!cls) return null;
    const student = cls.students.find(s => s.id === studentId);
    if (!student) return null;

    student.points += skill.points;
    cls.totalPoints += skill.points;

    const historyItem = {
      id: `h_${Date.now()}_${Math.random().toString(36).slice(2, 5)}`,
      skillName: skill.name,
      points: skill.points,
      type: skill.points >= 0 ? 'pos' : 'neg',
      icon: skill.icon,
      timestamp: Date.now(),
      note: skill.note || ''
    };
    student.history.unshift(historyItem);

    this.save();
    return { student, historyItem };
  }

  // Award points to whole class
  awardWholeClassPoint(classId, skill) {
    const cls = this.state.classes.find(c => c.id === classId);
    if (!cls) return null;

    cls.students.forEach(student => {
      student.points += skill.points;
      student.history.unshift({
        id: `h_all_${Date.now()}_${student.id}`,
        skillName: `[全班] ${skill.name}`,
        points: skill.points,
        type: skill.points >= 0 ? 'pos' : 'neg',
        icon: skill.icon,
        timestamp: Date.now()
      });
    });

    cls.totalPoints += skill.points * cls.students.length;
    this.save();
    return cls;
  }

  // Award points to multiple selected students
  awardMultipleStudents(classId, studentIds, skill) {
    const cls = this.state.classes.find(c => c.id === classId);
    if (!cls) return null;

    studentIds.forEach(id => {
      const student = cls.students.find(s => s.id === id);
      if (student) {
        student.points += skill.points;
        student.history.unshift({
          id: `h_multi_${Date.now()}_${student.id}`,
          skillName: skill.name,
          points: skill.points,
          type: skill.points >= 0 ? 'pos' : 'neg',
          icon: skill.icon,
          timestamp: Date.now()
        });
      }
    });

    cls.totalPoints += skill.points * studentIds.length;
    this.save();
    return cls;
  }

  // Set student attendance
  setAttendance(classId, studentId, status) {
    const cls = this.state.classes.find(c => c.id === classId);
    if (!cls) return;
    const student = cls.students.find(s => s.id === studentId);
    if (student) {
      student.attendance = status;
      this.save();
    }
  }

  // Hatch or customize monster
  updateStudentMonster(classId, studentId, monsterTraits) {
    const cls = this.state.classes.find(c => c.id === classId);
    if (!cls) return;
    const student = cls.students.find(s => s.id === studentId);
    if (student) {
      student.isHatched = true;
      student.monster = monsterTraits;
      this.save();
    }
  }

  // Add story post
  addStoryPost(classId, author, content, image = '') {
    const post = {
      id: `post_${Date.now()}`,
      author,
      classId,
      timestamp: Date.now(),
      content,
      image,
      likes: 0,
      liked: false,
      comments: []
    };
    this.state.stories.unshift(post);
    this.save();
    return post;
  }

  // Like story post
  togglePostLike(postId) {
    const post = this.state.stories.find(p => p.id === postId);
    if (!post) return;
    post.liked = !post.liked;
    post.likes += post.liked ? 1 : -1;
    this.save();
    return post;
  }

  // Add comment to post
  addPostComment(postId, author, text) {
    const post = this.state.stories.find(p => p.id === postId);
    if (!post) return;
    const comment = {
      id: `c_${Date.now()}`,
      author,
      text,
      time: '剛剛'
    };
    post.comments.push(comment);
    this.save();
    return comment;
  }

  // Send message
  sendMessage(studentId, sender, text) {
    if (!this.state.messages[studentId]) {
      this.state.messages[studentId] = [];
    }
    const msg = {
      id: `m_${Date.now()}`,
      sender, // 'teacher' | 'parent'
      text,
      timestamp: Date.now()
    };
    this.state.messages[studentId].push(msg);
    this.save();
    return msg;
  }

  // Submit portfolio work
  submitPortfolioWork(activityId, studentId, studentName, type, drawingData, caption) {
    const act = this.state.portfolios.find(a => a.id === activityId);
    if (!act) return;
    const sub = {
      id: `sub_${Date.now()}`,
      studentId,
      studentName,
      type,
      drawingData,
      caption,
      status: 'pending',
      timestamp: Date.now()
    };
    act.submissions.unshift(sub);
    this.save();
    return sub;
  }

  // Approve portfolio submission
  approvePortfolioSubmission(activityId, submissionId) {
    const act = this.state.portfolios.find(a => a.id === activityId);
    if (!act) return;
    const sub = act.submissions.find(s => s.id === submissionId);
    if (sub) {
      sub.status = 'approved';
      this.save();
    }
  }

  // Reset to demo data
  resetDemoData() {
    this.state = JSON.parse(JSON.stringify(INITIAL_DATA));
    this.save();
  }
}

export const store = new DojoStore();

/* ==========================================================================
   ClassDojo UI Design System & Global Styles
   ========================================================================== */

:root {
  --dojo-primary: #00af66;
  --dojo-primary-hover: #009657;
  --dojo-primary-light: #e6f9f0;
  --dojo-secondary: #00d27a;
  --dojo-blue: #3a86ff;
  --dojo-blue-light: #ebf3ff;
  --dojo-purple: #8338ec;
  --dojo-purple-light: #f3ebff;
  --dojo-yellow: #ffbe0b;
  --dojo-orange: #fb5607;
  --dojo-red: #ff4d6d;
  --dojo-red-light: #fff0f3;

  --text-main: #2b3b48;
  --text-muted: #6c7c8c;
  --text-light: #9aa7b2;

  --bg-page: #f4f7f9;
  --bg-card: #ffffff;
  --bg-hover: #f8fafc;
  --border-light: #e2e8f0;
  --border-card: #e5ebf0;

  --shadow-sm: 0 2px 4px rgba(43, 59, 72, 0.04);
  --shadow-md: 0 4px 12px rgba(43, 59, 72, 0.08);
  --shadow-lg: 0 10px 25px -5px rgba(43, 59, 72, 0.12);
  --shadow-hover: 0 8px 20px rgba(0, 175, 102, 0.15);

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans TC", sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  outline: none;
  transition: all 0.2s ease;
}

/* ==========================================================================
   Navigation Bar & Headers
   ========================================================================== */

.dojo-navbar {
  background-color: #ffffff;
  border-bottom: 1px solid var(--border-light);
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.dojo-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-main);
  text-decoration: none;
}

.dojo-logo-icon {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--dojo-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.4rem;
  box-shadow: 0 2px 6px rgba(0, 175, 102, 0.3);
}

.dojo-nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-link-btn {
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
}

.nav-link-btn:hover {
  background-color: var(--bg-hover);
  color: var(--text-main);
}

.nav-link-btn.active {
  background-color: var(--dojo-primary-light);
  color: var(--dojo-primary);
  font-weight: 700;
}

/* ==========================================================================
   Primary Buttons & UI Controls
   ========================================================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  font-size: 0.95rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  transition: transform 0.15s ease, box-shadow 0.2s ease, background-color 0.2s ease;
  user-select: none;
}

.btn:active {
