  box-shadow: 0 3px 8px rgba(0, 175, 102, 0.25);
}

.btn-primary:hover {
  background-color: var(--dojo-primary-hover);
  box-shadow: 0 5px 14px rgba(0, 175, 102, 0.35);
}

.btn-secondary {
  background-color: #ffffff;
  color: var(--text-main);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-sm);
}

.btn-secondary:hover {
