/* ==========================================================================
   Student Cards Grid
   ========================================================================== */

.roster-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 20px;
  padding: 20px 32px 120px;
