.roster-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 20px;
  padding: 20px 32px 120px;
  max-width: 1400px;
  margin: 0 auto;
  width: 100%;
}

.student-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 2px solid transparent;
  padding: 16px 12px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  user-select: none;
}

.student-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: #cbd5e1;
}

.student-card.selected {
  border-color: var(--dojo-blue);
  background-color: var(--dojo-blue-light);
}

.student-card.whole-class-card {
  background: linear-gradient(135deg, #ffffff 0%, #f0fdf4 100%);
  border: 2px dashed #86efac;
}

.student-card.whole-class-card:hover {
  border-color: var(--dojo-primary);
  background: #f0fdf4;
}

/* Points Badge */
.points-badge {
  position: absolute;
  top: 10px;
  right: 12px;
  min-width: 28px;
  height: 28px;
  padding: 0 6px;
  border-radius: var(--radius-full);
  background: var(--dojo-primary);
  color: #ffffff;
  font-weight: 800;
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 5px rgba(0, 175, 102, 0.4);
  z-index: 2;
}

.points-badge.negative {
  background: var(--dojo-red);
  box-shadow: 0 2px 5px rgba(255, 77, 109, 0.4);
}

.points-badge.zero {
  background: #94a3b8;
  box-shadow: none;
}

/* Monster Container */
.monster-avatar-wrap {
  width: 110px;
  height: 95px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
  position: relative;
}

.monster-avatar-wrap svg {
  max-width: 100%;
  max-height: 100%;
  filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.06));
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.student-card:hover .monster-avatar-wrap svg {
  transform: scale(1.08);
}

.student-name {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 140px;
}

.student-sub {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Attendance indicators */
.attendance-indicator {
  position: absolute;
  top: 10px;
  left: 12px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid #ffffff;
}

.att-present { background: var(--dojo-primary); }
.att-absent { background: var(--dojo-red); }
.att-tardy { background: var(--dojo-yellow); }
.att-left { background: var(--dojo-orange); }

/* Add Student Card */
.add-student-card {
  background: #f8fafc;
  border: 2px dashed #cbd5e1;
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  min-height: 160px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.add-student-card:hover {
  background: #f1f5f9;
  border-color: var(--dojo-primary);
}

.add-student-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--text-muted);
  margin-bottom: 10px;
}

.add-student-card:hover .add-student-icon {
  background: var(--dojo-primary-light);
  color: var(--dojo-primary);
}

