/**
 * ClassDojo Islands - Interactive Canvas 2D Playground Engine
 * Allows students and teachers to explore a virtual classroom island with their cute Dojo monsters!
 * Supports keyboard (WASD/Arrows), mouse click-to-move, and mobile touch joystick.
 */

export class DojoIslands {
  constructor(canvasId, options = {}) {
    this.canvas = document.getElementById(canvasId);
    if (!this.canvas) return;
    this.ctx = this.canvas.getContext('2d');
    this.options = options;

    this.width = this.canvas.width = options.width || 800;
    this.height = this.canvas.height = options.height || 500;

    // Player monster
    this.player = {
      x: 380,
      y: 260,
      targetX: 380,
      targetY: 260,
      speed: 3.5,
      name: options.playerName || '我 (Player)',
      color: options.playerColor || '#00d27a',
      bodyShape: options.playerShape || 'round',
      accessory: options.playerAccessory || 'party_hat',
      bounce: 0,
      bounceSpeed: 0.15,
      moving: false
    };

    // Classmate NPC monsters wandering on island
    this.classmates = [
      { name: 'Beyoncé', x: 260, y: 200, targetX: 260, targetY: 200, color: '#3a86ff', bubble: 'Dojo Islands 真好玩！', bubbleTimer: 180 },
      { name: 'Denzel', x: 500, y: 220, targetX: 500, targetY: 220, color: '#ffbe0b', bubble: '一起去噴泉許願吧！', bubbleTimer: 120 },
      { name: 'Jennifer', x: 420, y: 340, targetX: 420, targetY: 340, color: '#ff006e', bubble: '我拿到 1 點獎勵！', bubbleTimer: 240 },
      { name: 'Justin', x: 300, y: 320, targetX: 300, targetY: 320, color: '#8338ec', bubble: '嗨！今天大家都很棒！', bubbleTimer: 90 },
      { name: 'Leonardo', x: 550, y: 310, targetX: 550, targetY: 310, color: '#06d6a0', bubble: '水火箭實驗太酷了！', bubbleTimer: 300 }
    ];

    // Interactive hotspots
    this.hotspots = [
      { id: 'fountain', name: '💎 冒險星石泉', x: 400, y: 160, radius: 45, icon: '💎', collected: false },
      { id: 'campfire', name: '⛺ 篝火故事營', x: 220, y: 260, radius: 40, icon: '🔥' },
      { id: 'swing', name: '🎪 遊樂盪鞦韆', x: 580, y: 240, radius: 40, icon: '🎡' }
    ];

    this.keys = {};
    this.running = false;

    this.initEvents();
  }

  initEvents() {
    window.addEventListener('keydown', (e) => {
      this.keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener('keyup', (e) => {
      this.keys[e.key.toLowerCase()] = false;
    });

    // Canvas click-to-move
    this.canvas.addEventListener('click', (e) => {
      const rect = this.canvas.getBoundingClientRect();
      const scaleX = this.canvas.width / rect.width;
      const scaleY = this.canvas.height / rect.height;
      this.player.targetX = (e.clientX - rect.left) * scaleX;
      this.player.targetY = (e.clientY - rect.top) * scaleY;
    });

    // Touch support for mobile 393x852
    this.canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      const rect = this.canvas.getBoundingClientRect();
      const touch = e.touches[0];
      const scaleX = this.canvas.width / rect.width;
      const scaleY = this.canvas.height / rect.height;
      this.player.targetX = (touch.clientX - rect.left) * scaleX;
      this.player.targetY = (touch.clientY - rect.top) * scaleY;
    }, { passive: false });

    this.canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      const rect = this.canvas.getBoundingClientRect();
      const touch = e.touches[0];
      const scaleX = this.canvas.width / rect.width;
      const scaleY = this.canvas.height / rect.height;
      this.player.targetX = (touch.clientX - rect.left) * scaleX;
      this.player.targetY = (touch.clientY - rect.top) * scaleY;
    }, { passive: false });
  }

  start() {
    if (!this.running) {
      this.running = true;
      this.loop();
    }
  }

  stop() {
    this.running = false;
  }

  loop() {
    if (!this.running) return;
    this.update();
    this.render();
    requestAnimationFrame(() => this.loop());
  }

  update() {
    // Keyboard movement
    let dx = 0;
    let dy = 0;
    if (this.keys['arrowleft'] || this.keys['a']) dx -= this.player.speed;
    if (this.keys['arrowright'] || this.keys['d']) dx += this.player.speed;
    if (this.keys['arrowup'] || this.keys['w']) dy -= this.player.speed;
    if (this.keys['arrowdown'] || this.keys['s']) dy += this.player.speed;

    if (dx !== 0 || dy !== 0) {
      this.player.x += dx;
      this.player.y += dy;
      this.player.targetX = this.player.x;
      this.player.targetY = this.player.y;
      this.player.moving = true;
    } else {
      // Move towards click target
      const distTargetX = this.player.targetX - this.player.x;
      const distTargetY = this.player.targetY - this.player.y;
      const dist = Math.hypot(distTargetX, distTargetY);

      if (dist > 4) {
        this.player.x += (distTargetX / dist) * this.player.speed;
        this.player.y += (distTargetY / dist) * this.player.speed;
        this.player.moving = true;
      } else {
        this.player.moving = false;
      }
    }

    // Boundary constraints (stay within island)
    this.player.x = Math.max(120, Math.min(this.width - 120, this.player.x));
    this.player.y = Math.max(90, Math.min(this.height - 90, this.player.y));

    // Bounce animation
    if (this.player.moving) {
      this.player.bounce += this.player.bounceSpeed;
    } else {
      this.player.bounce = Math.sin(Date.now() / 300) * 0.15;
    }

    // Update classmate AI wandering
    this.classmates.forEach(c => {
      c.bubbleTimer--;
      if (c.bubbleTimer <= 0) {
        c.bubbleTimer = 200 + Math.random() * 200;
        c.targetX = c.x + (Math.random() - 0.5) * 80;
        c.targetY = c.y + (Math.random() - 0.5) * 80;
        c.targetX = Math.max(160, Math.min(this.width - 160, c.targetX));
        c.targetY = Math.max(120, Math.min(this.height - 120, c.targetY));
      }

      const cdx = c.targetX - c.x;
      const cdy = c.targetY - c.y;
      const cdist = Math.hypot(cdx, cdy);
      if (cdist > 2) {
        c.x += (cdx / cdist) * 0.8;
        c.y += (cdy / cdist) * 0.8;
      }
    });

    // Check interaction with hotspots
    this.hotspots.forEach(h => {
      const dist = Math.hypot(this.player.x - h.x, this.player.y - h.y);
      if (dist < h.radius) {
        if (h.id === 'fountain' && !h.collected) {
          h.collected = true;
          if (window.dojoAudio) window.dojoAudio.playFanfare();
          if (window.dojoConfetti) window.dojoConfetti.burst(h.x, h.y);
          if (this.options.onCollectGem) this.options.onCollectGem();
        }
      }
    });
  }

  render() {
    this.ctx.clearRect(0, 0, this.width, this.height);

    // 1. Water Background with gentle waves
    const time = Date.now() / 1000;
    this.ctx.fillStyle = '#60a5fa';
    this.ctx.fillRect(0, 0, this.width, this.height);

    // Wave ripples
    this.ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
    this.ctx.lineWidth = 2;
    for (let i = 0; i < 6; i++) {
      const wy = 40 + i * 80;
      this.ctx.beginPath();
      this.ctx.moveTo(0, wy + Math.sin(time + i) * 6);
      for (let x = 0; x < this.width; x += 40) {
        this.ctx.quadraticCurveTo(x + 20, wy + Math.sin(time + x * 0.02) * 8, x + 40, wy + Math.sin(time + i) * 6);
      }
      this.ctx.stroke();
    }

    // 2. Sand Beach
    this.ctx.fillStyle = '#fde68a';
    this.ctx.beginPath();
    this.ctx.ellipse(this.width / 2, this.height / 2 + 10, this.width * 0.44, this.height * 0.42, 0, 0, Math.PI * 2);
    this.ctx.fill();

    // 3. Lush Green Grass Island
    this.ctx.fillStyle = '#4ade80';
    this.ctx.beginPath();
    this.ctx.ellipse(this.width / 2, this.height / 2 + 10, this.width * 0.38, this.height * 0.35, 0, 0, Math.PI * 2);
    this.ctx.fill();

    // Inner darker green accents
    this.ctx.fillStyle = '#22c55e';
    this.ctx.beginPath();
    this.ctx.ellipse(this.width / 2, this.height / 2 + 10, this.width * 0.32, this.height * 0.28, 0, 0, Math.PI * 2);
    this.ctx.fill();

    // Cobblestone path
    this.ctx.strokeStyle = '#e2e8f0';
    this.ctx.lineWidth = 14;
    this.ctx.lineCap = 'round';
    this.ctx.beginPath();
    this.ctx.moveTo(220, 260);
    this.ctx.quadraticCurveTo(380, 240, 400, 160);
    this.ctx.quadraticCurveTo(460, 240, 580, 240);
    this.ctx.stroke();

    // 4. Render Hotspots
    this.hotspots.forEach(h => {
      // Hotspot glow ring
      this.ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
      this.ctx.beginPath();
      this.ctx.arc(h.x, h.y, h.radius, 0, Math.PI * 2);
      this.ctx.fill();

      // Hotspot icon & label
      this.ctx.font = '28px sans-serif';
      this.ctx.textAlign = 'center';
      this.ctx.textBaseline = 'middle';
      this.ctx.fillText(h.icon, h.x, h.y - 2);

      this.ctx.font = 'bold 12px sans-serif';
      this.ctx.fillStyle = '#1e293b';
      this.ctx.fillText(h.name, h.x, h.y + 28);
    });

    // Palm trees
    this.renderTree(170, 150);
    this.renderTree(620, 160);
    this.renderTree(200, 360);
    this.renderTree(590, 350);

    // 5. Render Classmates
    this.classmates.forEach(c => {
      this.renderMonsterSprite(c.x, c.y, c.color, c.name, 0.75);
      // Speech Bubble
      if (c.bubble) {
        this.ctx.font = 'bold 11px sans-serif';
        const tw = this.ctx.measureText(c.bubble).width;
        this.ctx.fillStyle = '#ffffff';
        this.ctx.strokeStyle = '#cbd5e1';
        this.ctx.lineWidth = 1.5;
        this.ctx.beginPath();
        this.ctx.roundRect(c.x - tw / 2 - 8, c.y - 48, tw + 16, 22, 10);
        this.ctx.fill();
        this.ctx.stroke();

        this.ctx.fillStyle = '#1e293b';
        this.ctx.textAlign = 'center';
        this.ctx.textBaseline = 'middle';
        this.ctx.fillText(c.bubble, c.x, c.y - 37);
      }
    });

    // 6. Render Player
    const bounceOffset = Math.sin(this.player.bounce * 8) * 4;
    this.renderMonsterSprite(this.player.x, this.player.y + bounceOffset, this.player.color, `🌟 ${this.player.name}`, 0.95, true);
  }

  renderTree(x, y) {
    // Trunk
    this.ctx.fillStyle = '#92400e';
    this.ctx.fillRect(x - 4, y, 8, 24);
    // Leaves
    this.ctx.fillStyle = '#15803d';
    this.ctx.beginPath();
    this.ctx.arc(x, y - 6, 18, 0, Math.PI * 2);
    this.ctx.fill();
    this.ctx.beginPath();
    this.ctx.arc(x - 10, y + 2, 14, 0, Math.PI * 2);
    this.ctx.fill();
    this.ctx.beginPath();
    this.ctx.arc(x + 10, y + 2, 14, 0, Math.PI * 2);
    this.ctx.fill();
  }

  renderMonsterSprite(x, y, color, name, scale = 1, isPlayer = false) {
    this.ctx.save();
    this.ctx.translate(x, y);
    this.ctx.scale(scale, scale);

    // Shadow
    this.ctx.fillStyle = 'rgba(0, 0, 0, 0.15)';
    this.ctx.beginPath();
    this.ctx.ellipse(0, 16, 18, 5, 0, 0, Math.PI * 2);
    this.ctx.fill();

    // Body
    this.ctx.fillStyle = color;
    this.ctx.beginPath();
    this.ctx.arc(0, 0, 18, 0, Math.PI * 2);
    this.ctx.fill();

    // Eyes
    this.ctx.fillStyle = '#ffffff';
    this.ctx.beginPath();
    this.ctx.arc(-6, -4, 5, 0, Math.PI * 2);
    this.ctx.arc(6, -4, 5, 0, Math.PI * 2);
    this.ctx.fill();

    // Pupils
    this.ctx.fillStyle = '#1e293b';
    this.ctx.beginPath();
    this.ctx.arc(-5, -4, 2.5, 0, Math.PI * 2);
    this.ctx.arc(5, -4, 2.5, 0, Math.PI * 2);
    this.ctx.fill();

    // Smile
    this.ctx.strokeStyle = '#1e293b';
    this.ctx.lineWidth = 1.8;
    this.ctx.beginPath();
    this.ctx.arc(0, 3, 5, 0, Math.PI);
    this.ctx.stroke();

    // Player hat or indicator
    if (isPlayer) {
      this.ctx.fillStyle = '#ffbe0b';
      this.ctx.beginPath();
      this.ctx.moveTo(0, -28);
      this.ctx.lineTo(-6, -18);
      this.ctx.lineTo(6, -18);
      this.ctx.closePath();
      this.ctx.fill();
    }

    this.ctx.restore();

    // Name tag
    this.ctx.font = isPlayer ? 'bold 12px sans-serif' : '11px sans-serif';
    this.ctx.fillStyle = isPlayer ? '#0f766e' : '#334155';
    this.ctx.textAlign = 'center';
    this.ctx.textBaseline = 'top';
    this.ctx.fillText(name, x, y + 18);
  }
}

/**
 * ClassDojo Reward Store & Points Redemption Engine
 * Enables students to redeem privileges using hard-earned points and teachers to approve redemptions.
 */

import { store } from './store.js';

export const DEFAULT_REWARDS = [
  { id: 'rew_leader', title: '一日班長特權', points: 10, icon: '👑', desc: '整天協助老師整隊、收發作業與擔任課堂小領航員！' },
  { id: 'rew_seat', title: '挑選夢想座位一週', points: 15, icon: '💺', desc: '可自由挑選心儀的學習座位一整週，與好朋友同心學習！' },
  { id: 'rew_chore', title: '免除值日生打掃一次', points: 15, icon: '🧹', desc: '獲得免除一次值日生責任券，由課堂小幫手支援！' },
  { id: 'rew_art', title: '課堂美術小幫手', points: 8, icon: '🎨', desc: '擔任美術課用具發放組長，作品優先陳列在公佈欄！' },
  { id: 'rew_lunch', title: '與班導師共享午餐', points: 25, icon: '🍕', desc: '週五午餐時間與導師暢聊心事與分享喜好，享用水果點心！' },
  { id: 'rew_dj', title: '課堂輕音樂點播權', points: 12, icon: '🎧', desc: '自習時間可為全班挑選一首喜愛的放鬆專注純音樂！' }
];

class RewardStore {
  constructor() {
    this.rewards = DEFAULT_REWARDS;
    this.redemptions = [];
  }

  getRewards() {
    return this.rewards;
  }

  getRedemptions(studentId = null) {
    if (studentId) {
      return this.redemptions.filter(r => r.studentId === studentId);
    }
    return this.redemptions;
  }

  // Student redeems reward
  redeem(studentId, rewardId) {
    const cls = store.getActiveClass();
    const student = cls.students.find(s => s.id === studentId);
    const reward = this.rewards.find(r => r.id === rewardId);

    if (!student || !reward) return { success: false, message: '查無學生或獎勵項目' };
    if (student.points < reward.points) {
      return { success: false, message: `點數不足！尚需 ${reward.points - student.points} 點` };
    }

    student.points -= reward.points;
    const redemption = {
      id: `rdm_${Date.now()}`,
      studentId: student.id,
      studentName: student.name,
      rewardId: reward.id,
      rewardTitle: reward.title,
      rewardIcon: reward.icon,
      pointsSpent: reward.points,
      status: 'approved', // instant pass or teacher review
      timestamp: Date.now()
    };

    this.redemptions.unshift(redemption);
    student.history.unshift({
      id: `h_rew_${Date.now()}`,
      skillName: `[兌換獎勵] ${reward.title}`,
      points: -reward.points,
      type: 'rew',
      icon: reward.icon,
      timestamp: Date.now(),
      note: `成功兌換：${reward.title}`
    });

    store.save();
    return { success: true, redemption };
  }

  // Teacher adds new reward
  addReward(title, points, icon = '🎁', desc = '') {
    const newRew = { id: `rew_${Date.now()}`, title, points, icon, desc };
    this.rewards.push(newRew);
    return newRew;
  }
}

export const rewardStore = new RewardStore();

