args.ReplacementContent:
.student-card {
  width: 118px;
  min-height: 156px;
  background: #ffffff;
  border-radius: 18px;
  border: 1.5px solid #fde68a;
  padding: 8px 6px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  box-shadow: 0 2px 6px rgba(180, 83, 9, 0.05);
  cursor: pointer;
  transition: transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.18s ease, border-color 0.18s ease;
  user-select: none;
}

.student-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 22px rgba(245, 158, 11, 0.16);
  border-color: #f59e0b;
}

.student-card.selected {
  border-color: #f59e0b;
  background-color: #fffbeb;
  box-shadow: 0 0 0 2.5px #f59e0b;
}

.student-card.whole-class-card {
  background: linear-gradient(180deg, #ffffff, #fefce8);
  border-color: #fde047;
}

/* Honey Drop Points Badge */
.points-badge {
  position: absolute;
  top: 4px;
  right: 6px;
  min-width: 28px;
  height: 28px;
  padding: 0 6px;
  border-radius: 10px;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #ffffff;
  font-weight: 800;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5;
  box-shadow: 0 2px 6px rgba(217, 119, 6, 0.35);
  border: 1.5px solid #ffffff;
}

.points-badge.negative {
  background: linear-gradient(135deg, #ef4444, #dc2626);
  box-shadow: 0 2px 6px rgba(220, 38, 38, 0.3);
}

.points-badge.zero {
  background: #94a3b8;
}

/* Bee Avatar Container */
.monster-avatar-wrap {
  width: 90px;
  height: 86px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 4px;
  margin-bottom: 6px;
  position: relative;
}

.monster-avatar-wrap img,
.monster-avatar-wrap svg {
  max-width: 100%;
  max-height: 100%;
  filter: drop-shadow(0 3px 6px rgba(180, 83, 9, 0.12));
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.student-card:hover .monster-avatar-wrap img,
.student-card:hover .monster-avatar-wrap svg {
  transform: scale(1.08) translateY(-2px);
}

@keyframes beeBob {
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  50% { transform: translateY(-4px) rotate(1.5deg); }
}

.crew-bee-bobbing {
  animation: beeBob 2.6s ease-in-out infinite;
}

@keyframes eggPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.04); }
}

.crew-egg-pulse {
  animation: eggPulse 2.2s ease-in-out infinite;
}

.student-name {
  font-size: 13px;
  font-weight: 700;
  color: #1e293b;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 104px;
  line-height: 1.2;
}

.student-sub {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Attendance indicators */
.attendance-indicator {
  position: absolute;
  top: 8px;
  left: 8px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1.5px solid #ffffff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
}

.att-present { background: #10b981; }
.att-absent { background: #ef4444; }
.att-tardy { background: #f59e0b; }
.att-left { background: #ea580c; }

/* Add Student Card - Honeycomb style */
.add-student-card {
  width: 118px;
  min-height: 156px;
  background: #fffdf5;
  border: 2px dashed #fcd34d;
  border-radius: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px 8px;

