  renderMonsterSprite(x, y, color, name, scale = 1, isPlayer = false) {
    this.ctx.save();
    this.ctx.translate(x, y);
    this.ctx.scale(scale, scale);

    const wingFlap = Math.sin(Date.now() / 70) * 0.35;

    // Translucent fluttering wings
    this.ctx.fillStyle = 'rgba(224, 242, 254, 0.85)';
    this.ctx.strokeStyle = '#bae6fd';
    this.ctx.lineWidth = 1.2;

    // Left Wing
    this.ctx.save();
    this.ctx.translate(-8, -12);
    this.ctx.rotate(-0.4 + wingFlap);
    this.ctx.beginPath();
    this.ctx.ellipse(0, -10, 8, 14, -0.2, 0, Math.PI * 2);
    this.ctx.fill();
    this.ctx.stroke();
    this.ctx.restore();

    // Right Wing
    this.ctx.save();
    this.ctx.translate(8, -12);
    this.ctx.rotate(0.4 - wingFlap);
    this.ctx.beginPath();
    this.ctx.ellipse(0, -10, 8, 14, 0.2, 0, Math.PI * 2);
    this.ctx.fill();
    this.ctx.stroke();
    this.ctx.restore();

    // Shadow
    this.ctx.fillStyle = 'rgba(0, 0, 0, 0.12)';
    this.ctx.beginPath();
    this.ctx.ellipse(0, 20, 16, 5, 0, 0, Math.PI * 2);
    this.ctx.fill();

    // Antennae
    this.ctx.strokeStyle = '#334155';
    this.ctx.lineWidth = 1.6;
    this.ctx.beginPath();
    this.ctx.moveTo(-5, -14);
    this.ctx.quadraticCurveTo(-10, -24, -12, -22);
    this.ctx.moveTo(5, -14);
    this.ctx.quadraticCurveTo(10, -24, 12, -22);
    this.ctx.stroke();

    this.ctx.fillStyle = '#f59e0b';
    this.ctx.beginPath();
    this.ctx.arc(-12, -22, 2.5, 0, Math.PI * 2);
    this.ctx.arc(12, -22, 2.5, 0, Math.PI * 2);
    this.ctx.fill();

    // Bee Oval Body
    this.ctx.fillStyle = color || '#f59e0b';
    this.ctx.beginPath();
    this.ctx.ellipse(0, 0, 18, 15, 0, 0, Math.PI * 2);
    this.ctx.fill();

    // Honeybee Stripes
    this.ctx.fillStyle = '#1e293b';
    this.ctx.beginPath();
    this.ctx.roundRect(-4, -13, 8, 26, 3);
    this.ctx.fill();

    // Eyes
    this.ctx.fillStyle = '#ffffff';
    this.ctx.beginPath();
    this.ctx.arc(-8, -2, 4.5, 0, Math.PI * 2);
    this.ctx.arc(2, -2, 4.5, 0, Math.PI * 2);
    this.ctx.fill();

    // Pupils
    this.ctx.fillStyle = '#1e293b';
    this.ctx.beginPath();
    this.ctx.arc(-7, -2, 2.2, 0, Math.PI * 2);
    this.ctx.arc(3, -2, 2.2, 0, Math.PI * 2);
    this.ctx.fill();

    // Smile
    this.ctx.strokeStyle = '#1e293b';
    this.ctx.lineWidth = 1.6;
    this.ctx.beginPath();
    this.ctx.arc(-2, 4, 3.5, 0, Math.PI);
    this.ctx.stroke();

    // Player Crown / Sparkle
    if (isPlayer) {
      this.ctx.fillStyle = '#f59e0b';
      this.ctx.font = '14px sans-serif';
      this.ctx.fillText('👑', 0, -24);
    }

    this.ctx.restore();

    // Name tag
    this.ctx.font = isPlayer ? 'bold 12px sans-serif' : '11px sans-serif';
    this.ctx.fillStyle = isPlayer ? '#b45309' : '#334155';
    this.ctx.textAlign = 'center';
    this.ctx.textBaseline = 'top';
    this.ctx.fillText(name, x, y + 18);
  }
}

args.TargetContent:
  renderMonsterSprite(x, y, color, name, scale = 1, isPlayer = false) {
    this.ctx.save();
    this.ctx.translate(x, y);
    this.ctx.scale(scale, scale);

    // Shadow
    this.ctx.fillStyle = 'rgba(0, 0, 0, 0.15)';
    this.ctx.beginPath();
    this.ctx.ellipse(0, 16, 18, 5, 0, 0, Math.PI * 2);
    this.ctx.fill();

    // Body
    this.ctx.fillStyle = color;
    this.ctx.beginPath();
    this.ctx.arc(0, 0, 18, 0, Math.PI * 2);
    this.ctx.fill();

    // Eyes
    this.ctx.fillStyle = '#ffffff';
    this.ctx.beginPath();
    this.ctx.arc(-6, -4, 5, 0, Math.PI * 2);
    this.ctx.arc(6, -4, 5, 0, Math.PI * 2);
    this.ctx.fill();

    // Pupils
    this.ctx.fillStyle = '#1e293b';
    this.ctx.beginPath();
    this.ctx.arc(-5, -4, 2.5, 0, Math.PI * 2);
    this.ctx.arc(5, -4, 2.5, 0, Math.PI * 2);
    this.ctx.fill();

    // Smile
    this.ctx.strokeStyle = '#1e293b';
    this.ctx.lineWidth = 1.8;
    this.ctx.beginPath();
    this.ctx.arc(0, 3, 5, 0, Math.PI);
    this.ctx.stroke();

    // Player hat or indicator
    if (isPlayer) {
      this.ctx.fillStyle = '#ffbe0b';
      this.ctx.beginPath();
      this.ctx.moveTo(0, -28);
      this.ctx.lineTo(-6, -18);
      this.ctx.lineTo(6, -18);
      this.ctx.closePath();
      this.ctx.fill();
    }

    this.ctx.restore();

    // Name tag
    this.ctx.font = isPlayer ? 'bold 12px sans-serif' : '11px sans-serif';
    this.ctx.fillStyle = isPlayer ? '#0f766e' : '#334155';
    this.ctx.textAlign = 'center';
    this.ctx.textBaseline = 'top';
    this.ctx.fillText(name, x, y + 18);
  }
}

