class DojoAudio {
  constructor() {
    this.ctx = null;
    let saved = null;
    try {
      saved = localStorage.getItem('crew_sound_enabled');
    } catch (e) {}
    this.enabled = saved !== null ? saved === '1' : true;
  }

  toggleMute() {
    this.enabled = !this.enabled;
    try {
      localStorage.setItem('crew_sound_enabled', this.enabled ? '1' : '0');
    } catch (e) {}
    return this.enabled;
  }

  isMuted() {
    return !this.enabled;
  }

